package oepul.o6_4

import data.bergmaehder as tabellen
import rego.v1

# Datumswerte sind lokale Kalendertage im ISO-Format.
valid_date(d) if {
	regex.match(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`, d)
	time.parse_rfc3339_ns(concat("", [d, "T00:00:00Z"]))
}

year_of(d) := to_number(substring(d, 0, 4)) if valid_date(d)
in_period(y) if y in numbers.range(2023, 2028)

contract_years(y) := tabellen.contracts[sprintf("%d", [y])].years

entry_timely(y, d) := ok if {
	valid_date(d)
	ok := timely_start(y, d)
}

default timely_start(_, _) := false

timely_start(y, d) if {
	y in {2023, 2024, 2025}
	year_of(d) == y - 1
}

switch_permitted(y, d, target) := ok if {
	contract_years(y)
	valid_date(d)
	ok := switch_window(y, d, target)
}

default switch_window(_, _, _) := false

switch_window(y, d, target) if {
	year_of(d) >= y
	d <= "2025-12-31"
	target in tabellen.switches["4"]
}

takeover_deadline(y) := sprintf("%d-04-17", [y]) if y in {2023, 2028}

else := sprintf("%d-04-15", [y]) if in_period(y)

takeover_timely(y, d) := ok if {
	valid_date(d)
	deadline := takeover_deadline(y)
	ok := within_calendar_window(d, y, deadline)
}

default within_calendar_window(_, _, _) := false

within_calendar_window(d, y, deadline) if {
	year_of(d) == y
	d <= deadline
}

takeover_possible(t, y) if {
	takeover_timely(y, t.date)
	t.new_to_measure
	t.submitted_online
	t.ama_approved
	t.transferred_ha > 0
	t.additional_ha >= 0
	t.additional_ha <= 0.5 * t.transferred_ha
}

counts(p, y) := count([d | some d in dates; year_of(d) == y]) if {
	dates := p.operations.cutting_dates
	is_array(dates)
	every d in dates { valid_date(d) }
}

expected_code(p, y) := "BM0" if counts(p, y) == 0

else := tabellen.methods[p.bergmahd.main_method] if counts(p, y) == 1

tariff_eur_ha(y, code) := row.eur_ha if {
	some row in tabellen.rates
	row.code == code
	y >= row.from_year
	y <= row.to_year
}

matrix_cell(a, b) := row.mark if {
	some row in tabellen.matrix
	row.row == a
	row.column == b
}

compatible_payment(q) := ok if {
	is_string(q.measure)
	is_string(q.component)
	ok := allowed_payment(q)
}

default allowed_payment(_) := false

allowed_payment(q) if {
	matrix_cell("4", q.measure) == "x1"
	tabellen.matrix_notes["1"]
	q.component == "punktförmiges Landschaftselement"
}

# Bei einzelnen unbekannten Werten bleibt die Prüfung offen. Eine feststehende
# Verletzung in derselben Liste hat Vorrang vor unbekannten anderen Einträgen.
criterion(p, "flaeche") := p.bergmahd.extensive_meadow
criterion(p, "siedlungsgrenze") := p.bergmahd.above_settlement_limit
criterion(p, "zweck") := p.bergmahd.difficult_management

criterion(p, "hoehe") := a > (0.5 * p.area_ha) if {
	a := p.bergmahd.area_above_1200m_ha
	is_number(a)
	a >= 0
	p.area_ha > 0
	a <= p.area_ha
}

criterion(p, "heimbetrieb") := p.bergmahd.above_home_farm if is_boolean(p.bergmahd.above_home_farm)

else if p.bergmahd.only_alpine_station

criterion(p, "maxmahd") := counts(p, input.farm.year) <= 1
criterion(p, "abtransport") if counts(p, input.farm.year) == 0

else := p.bergmahd.crop_removed if counts(p, input.farm.year) > 0

criterion(p, "haeckseln") := p.bergmahd.shredded == false if is_boolean(p.bergmahd.shredded)

complete_cut(p) := false if counts(p, input.farm.year) == 0

else := false if p.bergmahd.full_cut == false

else := false if p.bergmahd.crop_removed == false

else if {
	counts(p, input.farm.year) > 0
	p.bergmahd.full_cut
	p.bergmahd.crop_removed
}

criterion(p, "zweijahresmahd") if complete_cut(p)

else if {
	p.bergmahd.bound_previous_year
	p.bergmahd.previous_full_cut_removed
}

else := false if {
	p.bergmahd.bound_previous_year
	p.bergmahd.previous_full_cut_removed == false
	complete_cut(p) == false
}

# Im ersten Bindungsjahr ohne belegte Mahd ist das erste Zweijahresfenster offen.

grazing_ok(g, y) := ok if {
	year_of(g.date) == y
	is_boolean(g.aftermath)
	ok := aftermath_in_season(g, y)
} else if {
	year_of(g.date) != y
}

default aftermath_in_season(_, _) := false

aftermath_in_season(g, y) if {
	g.aftermath
	g.date >= sprintf("%d-08-16", [y])
}

material_ok(material) if material.kind == "eigene häusliche Abwässer"

else := false if {
	is_string(material.kind)
	not material.kind in {"Festmist", "eigene häusliche Abwässer"}
}

else := false if {
	material.kind == "Festmist"
	material.original_form == false
}

else := false if {
	material.kind == "Festmist"
	material.needs_based == false
}

else if {
	material.kind == "Festmist"
	material.original_form
	material.needs_based
}

criterion(p, "weide") := false if {
	some g in p.bergmahd.grazing
	grazing_ok(g, input.farm.year) == false
} else if {
	is_array(p.bergmahd.grazing)
	every g in p.bergmahd.grazing { grazing_ok(g, input.farm.year) }
}

criterion(p, "duenger") := false if {
	p.operations.fertilizer.mineral_n_kg_per_ha > 0
	is_number(p.operations.fertilizer.mineral_n_kg_per_ha)
}

else := false if {
	some m in p.bergmahd.materials
	material_ok(m) == false
}

else if {
	is_array(p.bergmahd.materials)
	every m in p.bergmahd.materials { material_ok(m) }
}

criterion(p, "psm") if p.operations.psm_used == false

else := p.bergmahd.only_organic_approved_actives if p.operations.psm_used

criterion(p, "nutzungsart") := p.bergmahd.declared_use == "Bergmähder" if is_string(p.bergmahd.declared_use)
criterion(p, "mahdcode") := p.bergmahd.declared_code == expected_code(p, input.farm.year) if is_string(p.bergmahd.declared_code)

criterion(p, "kombination") := false if {
	some q in p.bergmahd.other_payments
	compatible_payment(q) == false
}

else if {
	is_array(p.bergmahd.other_payments)
	every q in p.bergmahd.other_payments { compatible_payment(q) }
}

criterion(p, "lage") := p.bergmahd.country == "AT" if is_string(p.bergmahd.country)
criterion(p, "produktiv") := p.bergmahd.active_agricultural_use
criterion(p, "ausschluss") := false if p.bergmahd.mfa_identified == false

else := false if p.bergmahd.mainly_agricultural == false

else := false if p.bergmahd.gloez_element

else := false if p.bergmahd.land_category in tabellen.excluded_uses

else if {
	p.bergmahd.mfa_identified
	p.bergmahd.mainly_agricultural
	p.bergmahd.gloez_element == false
	is_string(p.bergmahd.land_category)
	not p.bergmahd.land_category in tabellen.excluded_uses
}

criterion(p, "nationalpark") := false if p.bergmahd.national_park in {"Neusiedlersee", "Donau-Auen"}

else if p.bergmahd.national_park == "kein"

else := p.bergmahd.relevant_park_restrictions == false if {
	is_string(p.bergmahd.national_park)
	is_boolean(p.bergmahd.relevant_park_restrictions)
}

criterion(p, "versuch") := p.bergmahd.trial_prevents_compliance == false if is_boolean(p.bergmahd.trial_prevents_compliance)
criterion(p, "op") := p.bergmahd.op_applies == false if is_boolean(p.bergmahd.op_applies)
criterion(p, "ueberlagerung") := p.bergmahd.public_overlap == false if is_boolean(p.bergmahd.public_overlap)
criterion(p, "ausgleich") := p.bergmahd.official_compensation == false if is_boolean(p.bergmahd.official_compensation)

check_keys := {"flaeche", "siedlungsgrenze", "zweck", "hoehe", "heimbetrieb", "zweijahresmahd", "maxmahd", "abtransport", "haeckseln", "weide", "duenger", "psm", "nutzungsart", "mahdcode", "kombination", "lage", "produktiv", "ausschluss", "nationalpark", "versuch", "op", "ueberlagerung", "ausgleich"}

checked(p, k) := v if {
	v := criterion(p, k)
	is_boolean(v)
} else := null

parcel_checks := {p.parcel_id: {k: checked(p, k) | some k in check_keys} |
	some p in input.land.parcels
	p.bergmahd.enrolled
	in_period(input.farm.year)
}

# Tarifwert vor allgemeiner Förderfähigkeitsprüfung, Flächen- und Prämiengrenzen.
parcel_tariffs := {p.parcel_id: {"code": code, "eur_ha": rate, "eur": p.area_ha * rate} |
	some p in input.land.parcels
	p.bergmahd.enrolled
	p.area_ha > 0
	code := expected_code(p, input.farm.year)
	rate := tariff_eur_ha(input.farm.year, code)
}

# Status der einzelnen Schlagprüfungen; Bemessungsgrundlage und Förderentscheidung
# bleiben auch bei einer Beanstandung getrennt abrufbar.
parcel_review[id] := {"violations": violations, "missing_or_pending": pending, "status": status} if {
	some id, checks in parcel_checks
	violations := {key | some key, value in checks; value == false}
	pending := {key | some key, value in checks; value == null}
	status := review_status(violations, pending)
}

review_status(v, _) := "beanstandet" if count(v) > 0

review_status(v, pending) := "offen" if {
	count(v) == 0
	count(pending) > 0
}

review_status(v, pending) := "erfüllt" if {
	count(v) == 0
	count(pending) == 0
}

package oepul.o6_4

import data.bergmaehder as tabellen
import rego.v1

farm_size_ok if {
	is_number(input.farm.oepul.first_year)
	input.farm.oepul.first_year >= 2023
	input.farm.oepul.first_year < input.farm.year
}

farm_size_ok if {
	input.farm.oepul.first_year == input.farm.year
	input.farm.oepul.protected_at_ha >= 0.5
	is_number(input.farm.oepul.protected_at_ha)
}

farm_size_ok if {
	input.farm.oepul.first_year == input.farm.year
	input.farm.oepul.countable_at_ha >= 1.5
	is_number(input.farm.oepul.countable_at_ha)
}

applicant_eligible if {
	a := input.farm.oepul.applicant
	a.legal_form in {"natürliche Person", "eingetragene Personengesellschaft", "juristische Person", "Personenvereinigung"}
	private_applicant(a)
	a.own_name_and_account
	a.disposal_of_claimed_land
	a.active_farmer
	a.agricultural_activity
}

private_applicant(a) if a.legal_form == "natürliche Person"

private_applicant(a) if {
	a.public_body_or_institution == false
	a.equivalent_public_control == false
	is_number(a.public_share_pct)
	a.public_share_pct >= 0
	a.public_share_pct <= 25
}

loss_limit(previous_ha) := max([0.5, min([5, previous_ha * 0.05])]) if previous_ha >= 0

recoverable_area(previous_ha, loss_ha) := loss_ha if {
	loss_ha > loss_limit(previous_ha)
	loss_ha <= previous_ha
} else := 0 if {
	loss_ha >= 0
	loss_ha <= previous_ha
	loss_ha <= loss_limit(previous_ha)
}

conversion_allowed(before, after) if {
	some c in tabellen.conversions
	c.from in {before, "Maßnahmenfläche"}
	c.to == after
}

# new_ha umfasst den gesamten zu prüfenden Zuwachs gegenüber der Basis.
# prebound_ha ist der darin enthaltene bereits gleich gebundene Anteil.
eligible_new_area(y, base_2025_ha, new_ha, prebound_ha) := new_ha if {
	y in {2024, 2025}
	prebound_ha >= 0
	prebound_ha <= new_ha
} else := allowed if {
	y in {2026, 2027, 2028}
	base_2025_ha >= 0
	prebound_ha >= 0
	prebound_ha <= new_ha
	allowed := prebound_ha + min([new_ha - prebound_ha, max([5, base_2025_ha * 0.5])])
}

cap_eur_ha(y, category) := row.eur_ha if {
	some row in tabellen.caps
	category == row.category
	y >= row.from_year
	y <= row.to_year
}

band_upper(b, ha) := ha if b.upper_ha == null

else := min([ha, b.upper_ha])

modulation_factor(ha) := sum(parts) / ha if {
	is_number(ha)
	ha > 0
	parts := [amount | some b in tabellen.modulation; amount := b.factor * max([0, band_upper(b, ha) - b.lower_ha])]
}

advance_limit(expected_eur) := 0.75 * expected_eur if {
	expected_eur >= 0
	input.farm.oepul.administrative_checks_complete
}

sanction_percent(y, stage) := row.percent if {
	some row in tabellen.sanctions
	row.stage == stage
	y >= row.from_year
	y <= row.to_year
}

repeated_full_reduction if {
	is_number(input.farm.oepul.full_reductions_this_contract)
	input.farm.oepul.full_reductions_this_contract >= 2
}

reduction_order := tabellen.reductions

point_eligible(e) if {
	e.kind in {"Baum", "Busch", "Baumgruppe", "Buschgruppe", "Streuobstbaum"}
	e.distance_land_m >= 0
	e.distance_land_m <= 5
	e.in_farm_control
	e.crown_diameter_m >= 2
	e.area_m2 > 0
	e.area_m2 <= 100
	spacing_ok(e)
	e.claimed
	e.maintained_all_year
	e.alpine_or_rough_pasture == false
	e.gloez8 == false
}

spacing_ok(e) if e.isolated

spacing_ok(e) if {
	is_number(e.nearest_distance_m)
	e.nearest_distance_m >= 5
}

orchard_species_ok(name, y) if {
	in_period(y)
	some species in tabellen.orchard_species
	species.name == name
	y >= species.from_year
}

crop_classes(name, y) := {row.category | some row in tabellen.crops; row.name == name; row.from_year <= y}

# Sätze einer erteilten GG-Projektauflage nach Wechsel in Naturschutz.
nat_distance_rate(code, y, km, annual) := row.eur_ha if {
	some row in tabellen.nat_distance_rates
	code == row.code
	annual == row.annual
	y >= row.from_year
	y <= row.to_year
	km > row.min_km_exclusive
	within_distance(km, row.max_km_inclusive)
}

within_distance(_, upper) if upper == null

within_distance(km, upper) if {
	is_number(upper)
	km <= upper
}

farm_calculations.Vertragsjahre := contract_years(input.farm.oepul.start_year)
farm_calculations["Antrag fristgerecht"] := entry_timely(input.farm.oepul.start_year, input.farm.oepul.application_date)
farm_calculations["Wechsel zulässig"] := switch_permitted(input.farm.oepul.start_year, input.farm.oepul.switch.date, input.farm.oepul.switch.target)
farm_calculations["Abgangstoleranz ha"] := loss_limit(input.farm.oepul.previous_measure_ha)
farm_calculations["Rückzahlungspflichtige Differenz ha"] := recoverable_area(input.farm.oepul.previous_measure_ha, input.farm.oepul.nonexempt_loss_ha)
farm_calculations["Prämienfähiger Zuwachs ha"] := eligible_new_area(input.farm.year, object.get(input.farm.oepul, "measure_2025_ha", null), input.farm.oepul.cumulative_gain_ha, gain_prebound(input.farm.year))
farm_calculations.Modulationsfaktor := modulation_factor(input.farm.oepul.home_modulation_ha)
farm_calculations["Obergrenze EUR/ha"] := cap_eur_ha(input.farm.year, "Regel")
farm_calculations["Maximale Teilzahlung EUR"] := advance_limit(input.farm.oepul.expected_payment_eur)
farm_calculations["Sanktionssatz Prozent"] := sanction_percent(input.farm.year, input.farm.oepul.assessed_stage)

gve_factor(category) := r if {
	some r in tabellen.gve
	r.category == category
}

stocking_class(rgve, forage_ha) := rgve >= (0.3 * forage_ha) if {
	is_number(rgve)
	rgve >= 0
	forage_ha > 0
}

drought_arable_area(state, district, y) if {
	y == 2026
	some r in tabellen.arable_drought_districts
	r.state == state
	r.district in {"*", district}
}

div_variant(code) := tabellen.div_variants[code]

# Gegenstand sind die in der allgemeinen Liste genannten Maßnahmen/Optionen.
measure_in_group(group, name) if {
	some row in tabellen.general_lists
	row.group == group
	row.entry == name
}

streuobst_eligible(e, y) if {
	point_eligible(e)
	e.kind == "Streuobstbaum"
	orchard_species_ok(e.species, y)
	e.tall_or_half_standard
	e.vigorous_large_crown
	e.shared_permanent_support == false
}

qualifying_point_elements[p.parcel_id] contains index if {
	some p in input.land.parcels
	p.bergmahd.enrolled
	some index, e in p.bergmahd.point_elements
	point_eligible(e)
}

farm_calculations["Übernahmefrist eingehalten"] := takeover_timely(input.farm.year, input.farm.oepul.takeover.date)
farm_calculations["Übernahmevoraussetzungen erfüllt"] if takeover_possible(input.farm.oepul.takeover, input.farm.year)

# Anerkannte Flächen- und Behördenentscheidungen bleiben bei der Rechtsfolgenprüfung eigenständig.
trial_records_ok(p) if {
	p.bergmahd.trial_prevents_compliance
	t := p.bergmahd.trial_documentation
	t.written_approval_available
	t.type_extent_location_recorded
	t.vf_declared
}

third_party_proof_ok(p) if {
	f := p.bergmahd.third_party_fault
	f.exclusive
	f.proof_available
	f.measure_op_declared
}

# SRL 1.12 sieht die Modulation vor der Obergrenze je Schlag vor.
# Die Eingabe umfasst alle obergrenzenrelevanten Beträge einschließlich LSE
# nach etwaigen inhaltlichen Kürzungen und vor der Modulation.
modulated_capped_eur(amount, ha, home_ha, year) := min([amount * modulation_factor(home_ha), ha * cap_eur_ha(year, "Regel")]) if {
	amount >= 0
	ha > 0
}

measure_name(code) := tabellen.matrix_measures[code]

farm_size_result if farm_size_ok

else := false if {
	input.farm.oepul.first_year == input.farm.year
	is_number(input.farm.oepul.protected_at_ha)
	is_number(input.farm.oepul.countable_at_ha)
	input.farm.oepul.protected_at_ha < 0.5
	input.farm.oepul.countable_at_ha < 1.5
}

else := null

farm_calculations["Betriebsmindestgröße erfüllt"] := farm_size_result

gain_prebound(y) := 0 if y in {2024, 2025}

else := input.farm.oepul.prebound_gain_ha

# Mögliche Rechtsfolgen aus dem Jahresnachweis, ohne vorgreifende Sanktionsstufe.
transfer_year_result(p) := "fortgeführt" if {
	t := p.bergmahd.transfer
	year_of(t.date) == input.farm.year
	t.continued_to_year_end
	t.successor_measure in {"4", "18", "19"}
}

else := "melden, OP, keine Jahresprämie" if {
	t := p.bergmahd.transfer
	year_of(t.date) == input.farm.year
	t.continued_to_year_end == false
}

parcel_procedure[p.parcel_id] := result if {
	some p in input.land.parcels
	p.bergmahd.enrolled
	result := transfer_year_result(p)
}

package oepul.o6_4_test

import data.oepul.o6_4 as bm
import rego.v1

parcel := {
	"parcel_id": "Schlag A", "area_ha": 2,
	"operations": {"cutting_dates": ["2025-08-01", "2026-08-03"], "psm_used": false},
	"bergmahd": {
		"enrolled": true, "extensive_meadow": true, "above_settlement_limit": true,
		"difficult_management": true, "area_above_1200m_ha": 1.01, "above_home_farm": true,
		"full_cut": true, "crop_removed": true, "shredded": false, "grazing": [],
		"materials": [], "main_method": "Motormäher", "declared_code": "BM2",
		"declared_use": "Bergmähder", "other_payments": [], "country": "AT",
		"active_agricultural_use": true, "land_category": "Bergmähder", "mfa_identified": true,
		"mainly_agricultural": true, "gloez_element": false, "national_park": "kein",
		"trial_prevents_compliance": false, "op_applies": false, "public_overlap": false, "official_compensation": false,
	},
}

changed(attrs) := object.union(parcel, {"bergmahd": attrs})
no_cut := object.union(parcel, {"operations": {"cutting_dates": []}, "bergmahd": {"declared_code": "BM0", "bound_previous_year": true, "previous_full_cut_removed": true}})
at(p) := {"farm": {"year": 2026}, "land": {"parcels": [p]}}

checks(p) := output if {
	out := bm.parcel_checks with input as at(p)
	output := out[p.parcel_id]
}

test_schlag_vom_profil_bis_zum_tarif if {
	inp := at(parcel)
	review := bm.parcel_review with input as inp
	review["Schlag A"].status == "erfüllt"
	rates := bm.parcel_tariffs with input as inp
	rates["Schlag A"] == {"code": "BM2", "eur_ha": 594, "eur": 1188}
}

test_auswahl_und_keine_mindestschlaggroesse if {
	p := object.union(parcel, {"area_ha": 0.01, "bergmahd": {"area_above_1200m_ha": 0.009}})
	other := object.union(parcel, {"parcel_id": "B", "bergmahd": {"enrolled": false}})
	result := bm.parcel_review with input as {"farm": {"year": 2026}, "land": {"parcels": [p, other]}}
	object.keys(result) == {"Schlag A"}
	result["Schlag A"].status == "erfüllt"
}

test_strikte_hoehenmehrheit if {
	checks(changed({"area_above_1200m_ha": 1})).hoehe == false
	checks(changed({"area_above_1200m_ha": 1.0001})).hoehe
	checks(changed({"above_home_farm": false})).heimbetrieb == false
	checks(changed({"above_settlement_limit": false})).siedlungsgrenze == false
}

test_keine_bewilligung_bei_fehlenden_daten if {
